//! Generic color types for the Smearor ecosystem.
//!
//! Channel-generic [`Color<T>`] (normalized `f64`/`f32` and byte `u8`),
//! hex parsing/formatting via `FromStr`/`Display` and consolidated color
//! operations. [`Palette<N, T>`] maps semantic color names to colors:
//! keys are either a [`PaletteDefinition`] enum (type-safe vocabulary,
//! generated by [`palette_definition!`]) or the dynamic [`NamedColor`].
//! `gtk4`/`cairo` conversions live behind feature gates.
//!
//! Semantic color types (`FigureColor`, `LineColor`, `PawnColor`, ...)
//! stay in consumer crates as thin newtype wrappers around [`Color<T>`].

mod alpha;
mod alpha_percent;
#[cfg(feature = "cairo")]
mod cairo;
mod color;
#[cfg(feature = "gtk4")]
mod gtk4;
mod luminance;
mod luminance_weights;
mod named_color;
mod palette;
mod palette_definition;
mod parse_color_error;
mod static_palette;

pub use alpha::Alpha;
pub use alpha_percent::AlphaPercent;
pub use color::Color;
pub use luminance::Luminance;
pub use luminance_weights::LuminanceWeights;
pub use named_color::NamedColor;
pub use palette::Palette;
pub use palette_definition::PaletteDefinition;
pub use parse_color_error::ParseColorError;
pub use static_palette::StaticPalette;
